function project(p,w,h){let x=p.x,y=p.y,z=p.z;const sx=zoom*1.12,sy=zoom*.62;if(camera==='orbit'||camera==='isometric'){const a=rot,xx=x*Math.cos(a)-z*Math.sin(a);z=x*Math.sin(a)+z*Math.cos(a);x=xx}if(camera==='front')return{x:w/2+x*sx,y:h*.73-y*sy};if(camera==='side')return{x:w/2+z*sx,y:h*.73-y*sy};if(camera==='top')return{x:w/2+x*sx,y:h*.50+z*sx};const a=(camera==='orbit'?0:-.55),xx=x*Math.cos(a)-z*Math.sin(a),zz=x*Math.sin(a)+z*Math.cos(a),yy=y-500,cy=yy*Math.cos(pitch)-zz*Math.sin(pitch),cz=yy*Math.sin(pitch)+zz*Math.cos(pitch);return{x:w/2+xx*sx,y:h*.53-cy*sy+cz*zoom*.34}}
