 const punchName=$('pp56PunchSelect')?String($('pp56PunchSelect').value||'').trim():String(b?.punch||'').trim();
 const same=(a,b)=>String(a||'').trim().toLowerCase()===String(b||'').trim().toLowerCase();
 // Algunos catálogos etiquetan type como "tool" o "press-brake-tool"; buscar el tipo en todos los campos descriptivos evita perder herramientas válidas.
 const punchMatches=catalog.filter(t=>pp56IsPunch(t)&&(!b?.punch||String(t.name||'').toLowerCase().includes(String(b.punch).replace(/punz[oó]n\s*/i,'').trim().toLowerCase())||String(b.punch).toLowerCase().includes(String(t.name||'').replace(/punz[oó]n\s*/i,'').trim().toLowerCase())));
